      var token = match? match[1]: undefined;
      if (!hasLoggedConversion(token)) {
        setCookieIfConversion(token);

      }
    });

    window.ShopifyAnalytics.lib.page(null,{"requestId":"dacb990e-aa8d-45ad-bf9b-6f104080f75a-1786182944","shopifyEmitted":true});

    var eventsListenerScript = document.createElement('script');
    eventsListenerScript.async = true;
    eventsListenerScript.src = "//www.cosrx.com/cdn/shopifycloud/storefront/assets/shop_events_listener-4e26a9ce.js";
    document.getElementsByTagName('head')[0].appendChild(eventsListenerScript);
})();

div.script:
function toggleCouponModal() {
  var overlay = document.getElementById('coupon-modal-overlay');
  var modal = document.getElementById('coupon-modal');
  var isOpen = overlay.style.display === 'flex';
  if (isOpen) {
    modal.style.transform = 'translateY(100%)';
    setTimeout(function(){ overlay.style.display = 'none'; }, 300);
  } else {
    overlay.style.display = 'flex';
    overlay.style.alignItems = 'flex-end';
    overlay.style.justifyContent = 'center';
    requestAnimationFrame(function(){
      requestAnimationFrame(function(){
        modal.style.transform = 'translateY(0)';
      });
    });
  }
}

function injectCouponLink() {
  var subtotal = document.querySelector('.subtotal');
  if (!subtotal || document.getElementById('coupon-inject-link')) return;
  var link = document.createElement('div');
  link.id = 'coupon-inject-link';
  link.style.cssText = 'margin:0 0 8px;';
  link.innerHTML = 'Click here to check available coupons (4 available)';
  subtotal.parentNode.insertBefore(link, subtotal);
}
document.addEventListener('DOMContentLoaded', function() {
  setTimeout(injectCouponLink, 500);
  setTimeout(injectCouponLink, 1500);
  setTimeout(injectCouponLink, 3000);
});

function closeCouponModalOutside(e) {
  if (e.target === document.getElementById('coupon-modal-overlay')) {
    toggleCouponModal();
  }
}
  navigator.clipboard.writeText(code).then(function() {
    // 버튼 텍스트 변경
    var buttons = document.querySelectorAll('#coupon-modal button[onclick]');
    buttons.forEach(function(btn) {
      if (btn.getAttribute('onclick') === "applyCoupon('" + code + "')") {
        var original = btn.textContent;
        btn.textContent = 'Copied!';
        btn.style.background = '#2a9c6e';
        setTimeout(function() {
          btn.textContent = original;
          btn.style.background = '#c0395a';
        }, 2000);
      }
    });
  }).catch(function() {
    // clipboard 실패시 fallback
    var dummy = document.createElement('input');
    document.body.appendChild(dummy);
    dummy.value = code;
    dummy.select();
    document.execCommand('copy');
    document.body.removeChild(dummy);
  });
}

body.script:
function getCurrentCountry(callback) {
  fetch('https://ipapi.co/json/')
    .then(response => response.json())
    .then(data => {
      const country = data.country_name;
      callback(country);
    })
    .catch(error => {
      console.error("Error getting IP geolocation data:", error);
      callback(null);
    });
}

getCurrentCountry(function(country) {
  if (country) {
    console.log("Current country:", country);
  } else {
    console.log("Unable to determine current country.");
  }
});

div.script:
setTimeout(() => {
  const EADivToMove = document.getElementById('ea-sticky-cart-root');
  // Append it to the body (moves it to the end)
  document.body.appendChild(EADivToMove);
}, 150);

(function () {
  const cartAttributes = {};

  // Helper function to retrieve the UTM from Url
  function getUTMFromUrl() {
    const url_string = window.location.href;
    const url = new URL(url_string);

    const utm_id = url.searchParams.get("utm_id");
    const utm_source = url.searchParams.get("utm_source");
    const utm_medium = url.searchParams.get("utm_medium");
    const utm_campaign = url.searchParams.get("utm_campaign");
    const utm_term = url.searchParams.get("utm_term");
    const ref = url.searchParams.get("ref");

    if (!utm_id && !utm_source && !utm_medium && !utm_campaign && !ref) {
      return null;
    }

    let utmParameters = {};

      if (utm_id) {
        utmParameters.utm_id = utm_id;
      }
      if (utm_source) {
        utmParameters.utm_source = utm_source;
      }
      if (utm_medium) {
        utmParameters.utm_medium = utm_medium;
      }
      if (utm_campaign) {
        utmParameters.utm_campaign = utm_campaign;
      }
      if (utm_term) {
        utmParameters.utm_term = utm_term;
      }
      if (ref) {
        utmParameters.ref = ref;
      }


    return Object.keys(utmParameters).length === 0
      ? null
      : utmParameters;
  }

  // Helper function to retrieve the UTM from Cookie
  function getUTMAttributes() {
    const urlUtmParams = getUTMFromUrl();

    if (urlUtmParams) {
        return urlUtmParams;
    }

    // No longer reading from deprecated Shopify cookies
    return undefined;
  }

  function saveUtmParameters() {
    const utmParams = getUTMAttributes();
    if (utmParams) {
      const cartHasUtmAttributes = Object.keys(cartAttributes).find(attributeKey => attributeKey.startsWith("utm_") || attributeKey === "ref");
      if (cartHasUtmAttributes) {
        // Don't call API if it already contains our UTM parameters
        return;
      }

      // Handle both Shopify.routes.root and routes.root_url for better compatibility
      var rootUrl = (window.Shopify && window.Shopify.routes && window.Shopify.routes.root) 
        || (window.routes && window.routes.root_url) 
        || '/';

      var updateCart = fetch(rootUrl + 'cart/update.js',
      {
        headers: {
          'Content-Type': 'application/json',
        },
        method: "POST",
        body: JSON.stringify({
          attributes: {
            ...utmParams
          },
        })
      })
      .then(response => response.json())
      .then(data => {
        return data
      });
    }
  }

  saveUtmParameters();
})();
